from lib import *
S = SS('l36')
steps = [
    step("git worktree add ../l36wt1 -b feature 之后,新目录里的 .git 不是目录而是一个文件,内容一行:gitdir: <主仓库>/.git/worktrees/l36wt1。主仓库的 .git/worktrees/l36wt1/ 里多了几个管理文件:HEAD、ORIG_HEAD、commondir、gitdir、index,以及 logs 和 refs 目录。", t=tl(S(1)), mark=lidx(S(1), 'gitdir: /work/l36/.git/worktrees/l36wt1'), done=lidx(S(1), 'HEAD', 'commondir', 'gitdir', 'index', 'logs', 'refs'), kv=KV([['新目录的 .git', '一个文件,指向管理目录'], ['管理目录', '主 .git/worktrees/<名>/'], ['里面', 'HEAD、index、gitdir、commondir、logs…']], ['新目录的 .git'])),
    step("管理文件的内容:HEAD 是 ref: refs/heads/feature(这个工作树自己的 HEAD);gitdir 是新目录的 .git 文件的路径(反向指针);commondir 是 ../..,指向主仓库的 .git(共享部分在哪里);index 是这个工作树自己的暂存区(137 字节的二进制文件);logs 下只有 HEAD(它自己的 HEAD reflog)。两个方向的指针让 git 能从任意一头找到另一头。", t=tl(S(2)), mark=lidx(S(2), 'commondir ../..', 'gitdir    /work/l36wt1/.git'), done=lidx(S(2), 'HEAD      ref: refs/heads/feature', 'index:'), kv=KV([['HEAD', '工作树自己的 HEAD'], ['gitdir', '指回新目录的 .git 文件'], ['commondir', '../..,共享数据在主 .git'], ['index', '自己的暂存区']], ['commondir'])),
    step("共享与独立:在 wt1 里 git add b.txt,主工作树的 git status 看不到它(暂存区是各自独立的),wt1 的 status 是 A  b.txt。git rev-parse --git-dir 在 wt1 里是 <主>/.git/worktrees/l36wt1,--git-common-dir 是 <主>/.git;--git-path 显示 HEAD 和 index 在各自的管理目录里,而 refs/heads/main、objects 在主 .git 里。git branch -vv 里 feature 前面有个 +,后面标着它检出在哪个工作树。在 wt1 里提交之后,主仓库马上看到 feature 上的新提交“wt1提交”(refs/heads 共享)。", t=tl(S(3)), mark=lidx(S(3), 'A  b.txt', '+ feature', 'wt1提交'), done=lidx(S(3), '--git-dir', 'worktrees/l36wt1/HEAD', 'refs/heads/main', 'objects'), kv=KV([['各自独立', 'HEAD、index、HEAD 的 reflog'], ['共享', 'objects、refs/heads、config…'], ['分支前的 +', '该分支检出在别的工作树']], ['共享'])),
    step("同一个分支不能同时在两个工作树里检出:git worktree add ../l36wt2 feature 报 fatal: 'feature' is already used by worktree at …。想再要一个工作树,可以用 --detach 脱离分支,git worktree list 列出三行:主工作树 [main]、l36wt1 [feature]、l36wt2 (detached HEAD)。", t=tl(S(4)), mark=lidx(S(4), "already used by worktree"), done=lidx(S(4), '(detached HEAD)', '[feature]', '[main]'), kv=KV([['一个分支', '同一时刻只能被一个工作树检出'], ['--detach', '不绑定分支,可以多个'], ['原因', '避免两个工作树同时移动同一个分支']], ['一个分支'])),
    step("手工 rm -rf 一个工作树目录,主仓库并不会立刻知道:.git/worktrees/ 下还有 l36wt2 的管理目录,git worktree list 把它标成 prunable。git worktree prune -v 输出 Removing worktrees/l36wt2: gitdir file points to non-existent location,管理目录被清掉,只剩 l36wt1。管理文件靠 gitdir 反向指针判断目录是否还在。", t=tl(S(5)), mark=lidx(S(5), 'prunable', 'Removing worktrees/l36wt2'), done=lidx(S(5), 'git worktree list', 'git worktree prune -v'), kv=KV([['rm -rf 工作树', '管理目录仍在,list 标 prunable'], ['prune', '依据 gitdir 指针清理'], ['建议', '用 git worktree remove']], ['prune'])),
    step("lock 防止被 prune:git worktree lock --reason '在移动硬盘上' 之后管理目录里多了 locked 文件,内容就是原因,list 标 locked(如果工作树在可移动的介质上,不会因为暂时找不到目录被 prune 掉)。unlock 之后 git worktree move 同时改两头的指针:新位置的 .git 文件和管理目录里的 gitdir 都指向新路径。最后 git worktree remove 删掉目录和管理文件,.git/worktrees 目录本身也没了,list 只剩主工作树 1 行。", t=tl(S(6)), mark=lidx(S(6), 'locked', '在移动硬盘上'), done=lidx(S(6), 'git worktree unlock', 'git worktree remove', 'No such file'), kv=KV([['lock', '管理目录里的 locked 文件,内容是原因'], ['move', '同时改 .git 文件与 gitdir'], ['remove', '删目录和管理文件']], ['move'])),
]
A = mkarti('l36', 36, 'Git,worktree,多工作树,.git/worktrees,真实验证,动画演示',
    '看 git worktree 在 .git/worktrees 里留下什么:新目录的 .git 是指向管理目录的文件;管理目录有 HEAD、index、gitdir(反向指针)、commondir(../..)和 logs;HEAD、index 各自独立,objects、refs/heads 共享;同一个分支不能被两个工作树检出;rm -rf 之后靠 prune 清理,lock 防止被清理,move 同时改两头的指针。',
    '想同时在两个分支上干活,又不想 clone 两份仓库,git worktree 是怎么做到的?这篇看它在 .git/worktrees 里写了哪些文件、哪些东西共享、哪些各有一份,以及删除、移动、锁定时发生什么。',
    [('3 样独立', '每个工作树各有自己的 HEAD、index 和 HEAD 的 reflog;objects 与 refs/heads 共享'), ('互指', '新目录的 .git 文件指向 .git/worktrees/<名>,管理目录里的 gitdir 又指回来'), ('prunable', '手工删掉工作树目录后,git worktree list 的标记,要 prune 才清理管理目录')],
    [('新目录里的 .git', '<p>附加工作树的 <code>.git</code> 是一个只有一行的文件:<code>gitdir: &lt;主仓库&gt;/.git/worktrees/&lt;名&gt;</code>。git 在这个目录里找 HEAD、index 等。</p>'),
     ('管理目录', '<p><code>.git/worktrees/&lt;名&gt;/</code> 里:<code>HEAD</code> 是这个工作树自己的 HEAD,<code>index</code> 是自己的暂存区,<code>gitdir</code> 是新目录 .git 文件的路径(反向指针),<code>commondir</code> 是 <code>../..</code>,<code>logs/HEAD</code> 是自己的 HEAD reflog。</p>'),
     ('共享与独立', '<p>对象库、<code>refs/heads</code>、配置都在主 .git 里共享:在一个工作树里提交,别的工作树马上能看到分支的新提交。HEAD、暂存区各自独立,在一个工作树里 add 不会影响另一个。</p>'),
     ('一个分支一个工作树', '<p>同一个分支不能同时在两个工作树里检出,否则两边会同时移动它;想多开可以 <code>--detach</code>。</p>'),
     ('手工删除与 prune', '<p>手工删除工作树目录,主仓库不知道;<code>git worktree list</code> 标 prunable,<code>git worktree prune</code> 依据 gitdir 反向指针判断目录不存在,清掉管理目录。</p>'),
     ('lock、move、remove', '<p><code>lock</code> 在管理目录里放 <code>locked</code> 文件(内容是原因),防止在移动硬盘上的工作树因为暂时找不到被 prune;<code>move</code> 同时更新新目录的 .git 文件和管理目录里的 gitdir;<code>remove</code> 删除目录和管理文件。</p>')],
    steps,
    [ENV_I_GIT + '。路径在输出里做了简化(<主>、<路径>);worktree 的管理目录文件列表来自 ls,内容来自 cat',
     '没有验证:每个工作树各自的 refs/bisect、refs/worktree/* 等 per-worktree 引用(只验证了 HEAD 与 index);worktree.guessRemote、extensions.worktreeConfig 的 per-worktree 配置;git worktree repair;bare 仓库配合 worktree;子模块在 worktree 里的行为;git gc 对其他工作树 HEAD 与 index 的保护'],
    'worktree')
